import sys, json, time
data = json.load(sys.stdin)
def extract_results(value):
    """Accept either the raw NetBox paginated wrapper ({count, results: [...]})
    or an already-queried plain array (if inline query extracts .results upstream)."""
    if isinstance(value, dict) and 'results' in value:
        return value['results']
    if isinstance(value, list):
        return value
    return []

devices = extract_results(data.get('devicelist'))
interfaces = extract_results(data.get('interfacelist'))

# Group interfaces under their parent device. Real NetBox interfaces reference the device
# via interface['device']['id']; fall back to matching interface['id'] directly if that
# shape isn't present (matches the sample data given, which mirrors the device shape).
interfaces_by_device = {}
for iface in interfaces:
    device_ref = iface.get('device') or {}
    device_id = device_ref.get('id', iface.get('id'))
    interfaces_by_device.setdefault(device_id, []).append(iface)

combined = []
for device in devices:
    device_type = device.get('device_type') or {}
    manufacturer = device_type.get('manufacturer') or {}
    device_id = device.get('id')
    device_interfaces = interfaces_by_device.get(device_id, [])

    combined.append({
        'id': device_id,
        'name': device.get('name'),
        'display': device.get('display'),
        'manufacturer': manufacturer.get('name'),
        'model': device_type.get('model'),
        'interface_count': len(device_interfaces),
        'interfaces': [i.get('name') for i in device_interfaces if i.get('name')],
    })

suffix = str(int(time.time()))
tags_payload = {
    'name': f'runcode-summary-tag-{suffix}',
    'slug': f'runcode-summary-tag-{suffix}',
    'description': devices[0]['name'] if devices else 'no-devices-found',
}

print(json.dumps({
    'device_count': len(devices),
    'devices': combined,
    'tags_payload': tags_payload,
}))
